<template><section class="panel"><div class="panel-title"><h2>{{$t(title)}}{{$t("项目队列")}}</h2><el-button size="small" icon="el-icon-refresh" @click="load">{{$t("刷新")}}</el-button></div><div class="toolbar"><el-input v-model.trim="q" clearable :placeholder="$t('患者姓名 / 病历号')" @keyup.enter.native="load"/><el-button @click="load">{{$t("查询")}}</el-button><el-tag size="small" effect="plain">{{$t("待处理 ")}}{{$t(pending)}}</el-tag></div><el-table :data="rows" v-loading="loading" stripe><el-table-column prop="case_number" :label="$t('病历号')" min-width="120"/><el-table-column prop="real_name" :label="$t('患者')" width="95"/><el-table-column prop="project_name" :label="$t('项目名称')" min-width="135"/><el-table-column :formatter="localizedCell" prop="doctor" :label="$t('申请医生')" min-width="95"/><el-table-column :label="$t('缴费')" width="95"><template slot-scope="s"><el-tag size="mini" :type="s.row.payment_status==='PAID'?'success':'warning'">{{$t(payment(s.row.payment_status))}}</el-tag></template></el-table-column><el-table-column :label="$t('执行状态')" width="115"><template slot-scope="s">{{$t(status(s.row.status))}}</template></el-table-column><el-table-column :label="$t('结果')" min-width="160"><template slot-scope="s"><span :class="{'muted':!s.row.result}">{{s.row.result||'尚未录入'}}</span></template></el-table-column><el-table-column v-if="canManage" :label="$t('操作')" min-width="135" fixed="right"><template slot-scope="s"><el-button v-if="s.row.status==='CREATED'&&s.row.payment_status==='PAID'" type="text" @click="advance(s.row,'登记')">{{$t("登记患者")}}</el-button><el-button v-if="s.row.status==='REGISTERED'" type="text" @click="advance(s.row,'开始')">{{$t("开始执行")}}</el-button><el-button v-if="s.row.status==='IN_PROGRESS'" type="text" @click="showResult(s.row)">{{$t("录入结果")}}</el-button><span v-if="s.row.status==='COMPLETED'||s.row.status==='CANCELLED'" class="muted">—</span></template></el-table-column></el-table><el-empty v-if="!loading&&!rows.length" :description="$t('目前没有符合条件的项目')"/><el-dialog :visible.sync="dialog" :title="$t('录入医技结果')" append-to-body width="550px"><p class="muted">{{selected&&selected.real_name}} · {{$t(selected&&selected.project_name)}}</p><el-input v-model="result" type="textarea" :rows="5" maxlength="10000" show-word-limit :placeholder="$t('请输入已完成项目的结果')"/><span slot="footer"><el-button @click="dialog=false">{{$t("取消")}}</el-button><el-button type="primary" :disabled="!result.trim()" @click="complete">{{$t("提交结果")}}</el-button></span></el-dialog></section></template>
<script>import api from '../api';export default{name:'Services',props:['user'],data(){return{q:'',rows:[],loading:false,dialog:false,selected:null,result:''}},computed:{type(){return this.$parent.page==='check'?'CHECK':this.$parent.page==='lab'?'LAB':'PROCEDURE'},title(){return{CHECK:'检查',LAB:'检验',PROCEDURE:'处置'}[this.type]},canManage(){return this.user.role==='ADMIN'||this.user.role===({CHECK:'EXAM',LAB:'LAB',PROCEDURE:'PROCEDURE'}[this.type])},pending(){return this.rows.filter(r=>r.status!=='COMPLETED'&&r.status!=='CANCELLED').length}},created(){this.load()},methods:{payment(x){return{PAID:'已缴费',UNPAID:'未缴费',REFUNDED:'已退费',CANCELLED:'已撤销'}[x]||'—'},status(x){return{CREATED:'待登记',REGISTERED:'已登记',IN_PROGRESS:'执行中',COMPLETED:'已完成',CANCELLED:'已撤销'}[x]||x},async load(){this.loading=true;try{this.rows=await api.get('/services',{params:{type:this.type,q:this.q}})}catch(e){this.$message.error(e.message)}finally{this.loading=false}},async advance(row,step){try{await this.$confirm(`确认${step}「${row.real_name}」的「${row.project_name}」？`,'执行确认',{type:'warning'})}catch{return}try{await api.post(`/services/${this.type}/${row.id}/start`);this.$message.success(`${step}成功`);this.load()}catch(e){this.$message.error(e.message)}},showResult(row){this.selected=row;this.result=row.result||'';this.dialog=true},async complete(){try{await this.$confirm('确定提交医技结果？提交后该项目将标记为完成。','结果提交确认',{type:'warning'})}catch{return}try{await api.post(`/services/${this.type}/${this.selected.id}/complete`,{result:this.result});this.$message.success('结果已提交');this.dialog=false;this.load()}catch(e){this.$message.error(e.message)}}}}</script>
